const upsertUserGroup = `-- name: UpsertUserGroup :one

INSERT INTO ai_user_groups (
  tenant_id, user_id, group_id, user_multiplier_override, created_by
) SELECT $1, $2, $3, $4, $5
FROM ai_groups g
WHERE g.id = $3 AND g.tenant_id = $1
ON CONFLICT (tenant_id, user_id, group_id) DO UPDATE SET
  user_multiplier_override = EXCLUDED.user_multiplier_override,
  updated_at          = now()
RETURNING id, tenant_id, user_id, group_id, user_multiplier_override, created_by, created_at, updated_at
`

type UpsertUserGroupParams struct {
	TenantID               string         `json:"tenant_id"`
	UserID                 string         `json:"user_id"`
	GroupID                pgtype.UUID    `json:"group_id"`
	UserMultiplierOverride pgtype.Numeric `json:"user_multiplier_override"`
	CreatedBy              pgtype.Text    `json:"created_by"`
}

// ============================================================================
// User Group CRUD (租户→用户：分组限制 + 覆盖倍率)
// ============================================================================
func (q *Queries) UpsertUserGroup(ctx context.Context, arg UpsertUserGroupParams) (AiUserGroup, error) {
	row := q.db.QueryRow(ctx, upsertUserGroup,
		arg.TenantID,
		arg.UserID,
		arg.GroupID,
		arg.UserMultiplierOverride,
		arg.CreatedBy,
	)
	var i AiUserGroup
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.UserID,
		&i.GroupID,
		&i.UserMultiplierOverride,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
